// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { LibAppStorage, AppStorage, CabalData, CabalPhase, GovernanceSettings, ClankerV4Settings } from "../libraries/LibAppStorage.sol";
import { LibDiamond } from "../libraries/LibDiamond.sol";
import "../../CabalTBA.sol";

/**
 * @title SettingsFacet
 * @notice Handles governance settings and admin functions
 */
contract SettingsFacet {
    // ============ Events ============

    event GovernanceSettingsUpdated(
        uint256 indexed cabalId,
        uint256 votingPeriod,
        uint256 quorumBps,
        uint256 majorityBps,
        uint256 proposalThreshold
    );

    event CabalPaused(uint256 indexed cabalId);
    event CabalUnpaused(uint256 indexed cabalId);

    event ContractAddressUpdated(string indexed name, address newAddress);
    event AllCabalsReset(uint256 previousCount);
    event CabalMetadataUpdated(uint256 indexed cabalId, string name, string symbol, string image);

    // ============ Errors ============

    error CabalNotActive();
    error OnlyTBA();
    error InvalidSettings();

    // ============ Governance Settings (called via proposal execution) ============

    /**
     * @notice Update governance settings for a Cabal
     * @dev This must be called by the TBA (via governance proposal)
     * @param cabalId The Cabal to update
     * @param newSettings The new governance settings
     */
    function updateGovernanceSettings(
        uint256 cabalId,
        GovernanceSettings calldata newSettings
    ) external {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);

        // Only TBA can call this (via executed proposal)
        if (msg.sender != cabal.tbaAddress) revert OnlyTBA();

        // Validate settings
        if (newSettings.votingPeriod == 0) revert InvalidSettings();
        if (newSettings.quorumBps > 10000) revert InvalidSettings();
        if (newSettings.majorityBps < 5000 || newSettings.majorityBps > 10000) revert InvalidSettings();

        cabal.settings = newSettings;

        emit GovernanceSettingsUpdated(
            cabalId,
            newSettings.votingPeriod,
            newSettings.quorumBps,
            newSettings.majorityBps,
            newSettings.proposalThreshold
        );
    }

    /**
     * @notice Pause a Cabal (emergency)
     * @dev Called by TBA via governance
     */
    function pauseCabal(uint256 cabalId) external {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (msg.sender != cabal.tbaAddress) revert OnlyTBA();

        cabal.phase = CabalPhase.Paused;
        emit CabalPaused(cabalId);
    }

    /**
     * @notice Unpause a Cabal
     * @dev Called by TBA via governance
     */
    function unpauseCabal(uint256 cabalId) external {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (msg.sender != cabal.tbaAddress) revert OnlyTBA();

        cabal.phase = CabalPhase.Active;
        emit CabalUnpaused(cabalId);
    }

    // ============ View Functions ============

    /**
     * @notice Get governance settings for a Cabal
     */
    function getGovernanceSettings(uint256 cabalId) external view returns (GovernanceSettings memory) {
        return LibAppStorage.getCabalData(cabalId).settings;
    }

    // ============ Admin Functions (Diamond Owner) ============

    /**
     * @notice Initialize contract addresses
     * @dev Only callable by Diamond owner, typically during deployment
     */
    function initializeAddresses(
        address cabalNFT,
        address tbaImplementation,
        address erc6551Registry,
        address clankerFactory,
        address clankerFeeLocker,
        address weth
    ) external {
        LibDiamond.enforceIsContractOwner();

        AppStorage storage s = LibAppStorage.appStorage();
        s.cabalNFT = cabalNFT;
        s.tbaImplementation = tbaImplementation;
        s.erc6551Registry = erc6551Registry;
        s.clankerFactory = clankerFactory;
        s.clankerFeeLocker = clankerFeeLocker;
        s.weth = weth;

        emit ContractAddressUpdated("cabalNFT", cabalNFT);
        emit ContractAddressUpdated("tbaImplementation", tbaImplementation);
        emit ContractAddressUpdated("erc6551Registry", erc6551Registry);
        emit ContractAddressUpdated("clankerFactory", clankerFactory);
        emit ContractAddressUpdated("clankerFeeLocker", clankerFeeLocker);
        emit ContractAddressUpdated("weth", weth);
    }

    /**
     * @notice Initialize Clanker V4 specific addresses
     * @dev Only callable by Diamond owner. Uses separate storage slot to avoid collision.
     */
    function initializeClankerAddresses(
        address clankerHook,
        address clankerLocker,
        address clankerMevModule,
        address clankerDevBuyExtension
    ) external {
        LibDiamond.enforceIsContractOwner();

        ClankerV4Settings storage c = LibAppStorage.clankerV4Settings();
        c.hook = clankerHook;
        c.locker = clankerLocker;
        c.mevModule = clankerMevModule;
        c.devBuyExtension = clankerDevBuyExtension;

        emit ContractAddressUpdated("clankerHook", clankerHook);
        emit ContractAddressUpdated("clankerLocker", clankerLocker);
        emit ContractAddressUpdated("clankerMevModule", clankerMevModule);
        emit ContractAddressUpdated("clankerDevBuyExtension", clankerDevBuyExtension);
    }

    /**
     * @notice Update a single contract address
     */
    function updateContractAddress(string calldata name, address newAddress) external {
        LibDiamond.enforceIsContractOwner();

        AppStorage storage s = LibAppStorage.appStorage();
        bytes32 nameHash = keccak256(bytes(name));

        if (nameHash == keccak256("cabalNFT")) s.cabalNFT = newAddress;
        else if (nameHash == keccak256("tbaImplementation")) s.tbaImplementation = newAddress;
        else if (nameHash == keccak256("erc6551Registry")) s.erc6551Registry = newAddress;
        else if (nameHash == keccak256("clankerFactory")) s.clankerFactory = newAddress;
        else if (nameHash == keccak256("clankerFeeLocker")) s.clankerFeeLocker = newAddress;
        else if (nameHash == keccak256("weth")) s.weth = newAddress;
        else {
            // Clanker V4 settings use separate storage
            ClankerV4Settings storage c = LibAppStorage.clankerV4Settings();
            if (nameHash == keccak256("clankerHook")) c.hook = newAddress;
            else if (nameHash == keccak256("clankerLocker")) c.locker = newAddress;
            else if (nameHash == keccak256("clankerMevModule")) c.mevModule = newAddress;
            else if (nameHash == keccak256("clankerDevBuyExtension")) c.devBuyExtension = newAddress;
        }

        emit ContractAddressUpdated(name, newAddress);
    }

    /**
     * @notice Reset all cabals - clears the tracking arrays
     * @dev Only callable by Diamond owner. Old cabal data stays in storage but is orphaned.
     */
    function resetAllCabals() external {
        LibDiamond.enforceIsContractOwner();

        AppStorage storage s = LibAppStorage.appStorage();

        uint256 previousCount = s.allCabalIds.length;

        // Clear the cabal IDs array
        delete s.allCabalIds;

        // Reset the counter to start fresh
        s.nextCabalId = 0;

        emit AllCabalsReset(previousCount);
    }

    /**
     * @notice Re-add a cabal to the index (owner only)
     * @dev Used to fix index after reset if cabal data still exists
     */
    function reindexCabal(uint256 cabalId) external {
        LibDiamond.enforceIsContractOwner();

        AppStorage storage s = LibAppStorage.appStorage();

        // Check cabal exists (has a TBA)
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        require(cabal.tbaAddress != address(0), "Cabal does not exist");

        // Check not already indexed
        for (uint256 i = 0; i < s.allCabalIds.length; i++) {
            if (s.allCabalIds[i] == cabalId) {
                revert("Already indexed");
            }
        }

        // Add to index
        s.allCabalIds.push(cabalId);

        // Update nextCabalId if needed
        if (cabalId >= s.nextCabalId) {
            s.nextCabalId = cabalId + 1;
        }
    }

    /**
     * @notice Emergency recovery of ETH from a cabal's TBA (owner only)
     * @dev Only use for recovery purposes - this bypasses normal governance
     */
    function recoverETHFromCabal(uint256 cabalId, address payable recipient, uint256 amount) external {
        LibDiamond.enforceIsContractOwner();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        require(cabal.tbaAddress != address(0), "Cabal does not exist");

        // Execute ETH transfer from TBA
        CabalTBA(payable(cabal.tbaAddress)).executeCall(recipient, amount, "");
    }

    /**
     * @notice Emergency recovery of tokens from a cabal's TBA (owner only)
     * @dev Only use for recovery purposes - this bypasses normal governance
     */
    function recoverTokensFromCabal(uint256 cabalId, address token, address recipient, uint256 amount) external {
        LibDiamond.enforceIsContractOwner();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        require(cabal.tbaAddress != address(0), "Cabal does not exist");

        // Execute token transfer from TBA
        CabalTBA(payable(cabal.tbaAddress)).executeCall(
            token,
            0,
            abi.encodeWithSignature("transfer(address,uint256)", recipient, amount)
        );
    }

    /**
     * @notice Get contract addresses
     */
    function getContractAddresses() external view returns (
        address cabalNFT,
        address tbaImplementation,
        address erc6551Registry,
        address clankerFactory,
        address clankerFeeLocker,
        address weth
    ) {
        AppStorage storage s = LibAppStorage.appStorage();
        return (
            s.cabalNFT,
            s.tbaImplementation,
            s.erc6551Registry,
            s.clankerFactory,
            s.clankerFeeLocker,
            s.weth
        );
    }

    /**
     * @notice Get Clanker V4 specific addresses
     */
    function getClankerAddresses() external view returns (
        address clankerHook,
        address clankerLocker,
        address clankerMevModule,
        address clankerDevBuyExtension
    ) {
        ClankerV4Settings storage c = LibAppStorage.clankerV4Settings();
        return (
            c.hook,
            c.locker,
            c.mevModule,
            c.devBuyExtension
        );
    }

    /**
     * @notice Update cabal metadata (name, symbol, image) - admin only
     * @dev This updates the CabalData storage. Note: The on-chain ERC-20 token's 
     *      name() and symbol() cannot be changed after deployment.
     * @param cabalId The cabal to update
     * @param name New name for the cabal
     * @param symbol New symbol for the cabal
     * @param image New image URI for the cabal
     */
    function updateCabalMetadata(
        uint256 cabalId,
        string calldata name,
        string calldata symbol,
        string calldata image
    ) external {
        LibDiamond.enforceIsContractOwner();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        require(cabal.tbaAddress != address(0), "Cabal does not exist");

        cabal.name = name;
        cabal.symbol = symbol;
        cabal.image = image;

        emit CabalMetadataUpdated(cabalId, name, symbol, image);
    }
}

contracts/cabal/diamond/facets/StakingFa.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { LibAppStorage, AppStorage, CabalData, CabalPhase, ActivityType } from "../libraries/LibAppStorage.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

/**
 * @title StakingFacet
 * @notice Handles staking/unstaking of Cabal tokens for voting power
 */
contract StakingFacet {
    // ============ Events ============

    event Staked(
        uint256 indexed cabalId,
        address indexed user,
        uint256 amount,
        uint256 newBalance
    );

    event Unstaked(
        uint256 indexed cabalId,
        address indexed user,
        uint256 amount,
        uint256 newBalance
    );

    // ============ Errors ============

    error CabalNotActive();
    error InsufficientBalance();
    error ZeroAmount();
    error TransferFailed();

    // ============ External Functions ============

    /**
     * @notice Stake tokens to gain voting power
     * @param cabalId The Cabal to stake in
     * @param amount Amount of tokens to stake
     */
    function stake(uint256 cabalId, uint256 amount) external {
        if (amount == 0) revert ZeroAmount();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.phase != CabalPhase.Active) revert CabalNotActive();

        // Transfer tokens from user to TBA (treasury holds staked tokens)
        bool success = IERC20(cabal.tokenAddress).transferFrom(
            msg.sender,
            cabal.tbaAddress,
            amount
        );
        if (!success) revert TransferFailed();

        _stakeInternal(cabalId, amount, cabal);
    }

    /**
     * @notice Stake tokens with EIP-2612 permit (single transaction, no separate approval)
     * @param cabalId The Cabal to stake in
     * @param amount Amount of tokens to stake
     * @param deadline Permit signature deadline
     * @param v Signature v component
     * @param r Signature r component
     * @param s Signature s component
     */
    function stakeWithPermit(
        uint256 cabalId,
        uint256 amount,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        if (amount == 0) revert ZeroAmount();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.phase != CabalPhase.Active) revert CabalNotActive();

        // Execute permit to approve this contract
        IERC20Permit(cabal.tokenAddress).permit(
            msg.sender,
            address(this),
            amount,
            deadline,
            v,
            r,
            s
        );

        // Transfer tokens from user to TBA
        bool success = IERC20(cabal.tokenAddress).transferFrom(
            msg.sender,
            cabal.tbaAddress,
            amount
        );
        if (!success) revert TransferFailed();

        _stakeInternal(cabalId, amount, cabal);
    }

    // ============ Internal Functions ============

    /**
     * @notice Internal stake logic (shared by stake and stakeWithPermit)
     */
    function _stakeInternal(uint256 cabalId, uint256 amount, CabalData storage cabal) internal {
        // Update staked balance
        uint256 currentStake = LibAppStorage.getStakedBalance(cabalId, msg.sender);
        uint256 newBalance = currentStake + amount;
        LibAppStorage.setStakedBalance(cabalId, msg.sender, newBalance);

        // Update total staked
        cabal.totalStaked += amount;

        // Track that user has stake in this cabal (for indexing)
        if (currentStake == 0) {
            LibAppStorage.getUserStakedCabals(msg.sender).push(cabalId);
        }

        // Update delegated power if user has delegated
        address delegatee = LibAppStorage.getDelegatee(cabalId, msg.sender);
        if (delegatee != address(0)) {
            uint256 currentDelegatedPower = LibAppStorage.getDelegatedPower(cabalId, delegatee);
            LibAppStorage.setDelegatedPower(cabalId, delegatee, currentDelegatedPower + amount);
        }

        // Clear child creation vote - stake changed, must re-vote with new weight
        _clearChildCreationVote(cabalId, msg.sender);

        emit Staked(cabalId, msg.sender, amount, newBalance);

        LibAppStorage.logActivity(cabalId, msg.sender, ActivityType.Staked, amount);
    }

    /**
     * @notice Unstake tokens
     * @param cabalId The Cabal to unstake from
     * @param amount Amount of tokens to unstake
     */
    function unstake(uint256 cabalId, uint256 amount) external {
        if (amount == 0) revert ZeroAmount();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.phase != CabalPhase.Active) revert CabalNotActive();

        uint256 currentStake = LibAppStorage.getStakedBalance(cabalId, msg.sender);
        if (amount > currentStake) revert InsufficientBalance();

        uint256 newBalance = currentStake - amount;
        LibAppStorage.setStakedBalance(cabalId, msg.sender, newBalance);

        // Update total staked
        cabal.totalStaked -= amount;

        // Update delegated power if user has delegated (safe subtraction to prevent revert)
        address delegatee = LibAppStorage.getDelegatee(cabalId, msg.sender);
        if (delegatee != address(0)) {
            uint256 currentDelegatedPower = LibAppStorage.getDelegatedPower(cabalId, delegatee);
            uint256 newDelegatedPower = currentDelegatedPower > amount ? currentDelegatedPower - amount : 0;
            LibAppStorage.setDelegatedPower(cabalId, delegatee, newDelegatedPower);
        }

        // Clear child creation vote - stake changed, must re-vote with new weight
        _clearChildCreationVote(cabalId, msg.sender);

        // Transfer tokens from TBA back to user
        bytes memory transferCalldata = abi.encodeWithSelector(
            IERC20.transfer.selector,
            msg.sender,
            amount
        );

        // Import CabalTBA for executeCall
        (bool success, ) = cabal.tbaAddress.call(
            abi.encodeWithSignature(
                "executeCall(address,uint256,bytes)",
                cabal.tokenAddress,
                0,
                transferCalldata
            )
        );
        if (!success) revert TransferFailed();

        emit Unstaked(cabalId, msg.sender, amount, newBalance);

        LibAppStorage.logActivity(cabalId, msg.sender, ActivityType.Unstaked, amount);
    }

    /**
     * @notice Clear a user's child creation vote when their stake changes
     * @dev Subtracts vote weight from totals and clears the vote record
     */
    function _clearChildCreationVote(uint256 cabalId, address user) internal {
        // Get current vote (returns 0 if stale due to nonce mismatch)
        uint256 currentVote = LibAppStorage.getChildCreationVote(cabalId, user);
        if (currentVote == 0) return; // No active vote to clear

        // Get vote weight and subtract from appropriate total
        uint256 voteWeight = LibAppStorage.getChildCreationVoteWeight(cabalId, user);

        if (currentVote == 1) {
            // Voted YES - subtract from votesFor
            uint256 currentVotesFor = LibAppStorage.getChildCreationVotesFor(cabalId);
            if (voteWeight <= currentVotesFor) {
                LibAppStorage.setChildCreationVotesFor(cabalId, currentVotesFor - voteWeight);
            } else {
                LibAppStorage.setChildCreationVotesFor(cabalId, 0);
            }
        } else if (currentVote == 2) {
            // Voted NO - subtract from votesAgainst
            uint256 currentVotesAgainst = LibAppStorage.getChildCreationVotesAgainst(cabalId);
            if (voteWeight <= currentVotesAgainst) {
                LibAppStorage.setChildCreationVotesAgainst(cabalId, currentVotesAgainst - voteWeight);
            } else {
                LibAppStorage.setChildCreationVotesAgainst(cabalId, 0);
            }
        }

        // Clear the vote record
        LibAppStorage.clearChildCreationVote(cabalId, user);
    }

    // ============ View Functions ============

    /**
     * @notice Get staked balance for a user
     */
    function getStakedBalance(uint256 cabalId, address user) external view returns (uint256) {
        return LibAppStorage.getStakedBalance(cabalId, user);
    }

    /**
     * @notice Get voting power for a user (staked tokens + delegated power)
     */
    function getVotingPower(uint256 cabalId, address user) external view returns (uint256) {
        // Tokens are now auto-staked at launch, so just use staked balance
        uint256 ownStake = LibAppStorage.getStakedBalance(cabalId, user);
        uint256 delegatedToMe = LibAppStorage.getDelegatedPower(cabalId, user);

        // If user has delegated, they lose their own stake as voting power
        address delegatee = LibAppStorage.getDelegatee(cabalId, user);
        if (delegatee != address(0)) {
            return delegatedToMe; // Only delegated power, not own stake
        }

        return ownStake + delegatedToMe;
    }

    /**
     * @notice Get total staked in a Cabal
     */
    function getTotalStaked(uint256 cabalId) external view returns (uint256) {
        return LibAppStorage.getCabalData(cabalId).totalStaked;
    }

    /**
     * @notice Get all Cabals a user has staked in
     */
    function getUserStakedCabals(address user) external view returns (uint256[] memory) {
        return LibAppStorage.getUserStakedCabals(user);
    }
}

contracts/cabal/diamond/facets/StorageRe.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { LibAppStorage, AppStorage } from "../libraries/LibAppStorage.sol";
import { LibDiamond } from "../libraries/LibDiamond.sol";

/**
 * @title StorageRepairFacet
 * @notice One-time use facet to repair corrupted storage
 * @dev Should be removed after repair is complete
 */
contract StorageRepairFacet {
    event StorageRepaired(uint256 nextCabalId);

    /**
     * @notice Repair the corrupted nextCabalId and allCabalIds
     * @param correctNextCabalId The correct value for nextCabalId
     */
    function repairStorage(uint256 correctNextCabalId) external {
        LibDiamond.enforceIsContractOwner();

        AppStorage storage s = LibAppStorage.appStorage();

        // Fix nextCabalId (was overwritten with hook address)
        s.nextCabalId = correctNextCabalId;

        // Clear allCabalIds array (was corrupted)
        // We can't easily delete a dynamic array, but we can set length to 0
        // by writing directly to the length slot
        assembly {
            // allCabalIds is at slot 7 relative to AppStorage base
            // Get the storage position
            let baseSlot := s.slot
            let arraySlot := add(baseSlot, 7)
            // Set length to 0
            sstore(arraySlot, 0)
        }

        emit StorageRepaired(correctNextCabalId);
    }

    /**
     * @notice Check current storage state
     */
    function checkStorage() external view returns (
        uint256 nextCabalId,
        uint256 allCabalIdsLength
    ) {
        AppStorage storage s = LibAppStorage.appStorage();
        return (s.nextCabalId, s.allCabalIds.length);
    }
}

contracts/cabal/diamond/facets/SwapFacet.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { LibAppStorage, AppStorage, CabalData, CabalPhase, ClankerV4Settings, ActivityType } from "../libraries/LibAppStorage.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

// Uniswap V4 imports
import { Commands } from "@uniswap/universal-router/contracts/libraries/Commands.sol";
import { Actions } from "@uniswap/v4-periphery/src/libraries/Actions.sol";
import { IV4Router } from "@uniswap/v4-periphery/src/interfaces/IV4Router.sol";
import { PoolKey } from "@uniswap/v4-core/src/types/PoolKey.sol";
import { Currency } from "@uniswap/v4-core/src/types/Currency.sol";
import { IHooks } from "@uniswap/v4-core/src/interfaces/IHooks.sol";

/**
 * @title IUniversalRouter
 */
interface IUniversalRouter {
    function execute(
        bytes calldata commands,
        bytes[] calldata inputs,
        uint256 deadline
    ) external payable;
}

/**
 * @title IPermit2
 */
interface IPermit2 {
    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
}

/**
 * @title IWETH
 */
interface IWETH {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title SwapFacet
 * @notice Handles token swaps via Uniswap V4 for Cabal tokens
 * @dev Uses Universal Router with official Uniswap V4 encoding pattern.
 *      Trading fees (1%) are enforced at the Clanker hook level and collected in ClankerFeeLocker.
 *      99% of fees go to the cabal's TBA, 1% to CABAL0's TBA (protocol treasury).
 */
contract SwapFacet {
    // ============ Constants ============

    // Universal Router on Base
    address constant UNIVERSAL_ROUTER = 0x6fF5693b99212Da76ad316178A184AB56D299b43;
    address constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    address constant WETH = 0x4200000000000000000000000000000000000006;

    // ActionConstants from Uniswap V4
    address constant MSG_SENDER = address(1);
    address constant ADDRESS_THIS = address(2);

    // Dynamic Fee Flag (0x800000)
    uint24 constant DEFAULT_FEE = 8388608; 
    int24 constant DEFAULT_TICK_SPACING = 200;

    // ============ Events ============

    event TokensBought(uint256 indexed cabalId, address indexed buyer, uint256 ethAmount, uint256 tokensReceived);
    event TokensSold(uint256 indexed cabalId, address indexed seller, uint256 tokenAmount, uint256 ethReceived);

    // ============ Errors ============

    error CabalNotActive();
    error CabalClosed();
    error ZeroAmount();
    error InsufficientBalance();
    error SlippageExceeded();
    error InvalidToken();

    // ============ Buy Function ============

    /**
     * @notice Buy Cabal tokens with ETH
     * @param cabalId The Cabal ID to buy tokens from
     * @param minAmountOut Minimum tokens expected (slippage protection)
     */
    function buyTokens(
        uint256 cabalId,
        uint256 minAmountOut
    ) external payable returns (uint256 amountOut) {
        return buyTokensWithHookData(cabalId, minAmountOut, bytes(""));
    }

    /**
     * @notice Buy Cabal tokens with hook data
     * @dev Trading fees are handled at the Clanker hook level (collected in ClankerFeeLocker)
     */
    function buyTokensWithHookData(
        uint256 cabalId,
        uint256 minAmountOut,
        bytes memory hookData
    ) public payable returns (uint256 amountOut) {
        if (msg.value == 0) revert ZeroAmount();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.phase != CabalPhase.Active) revert CabalNotActive();
        if (cabal.phase == CabalPhase.Closed) revert CabalClosed();
        if (cabal.tokenAddress == address(0)) revert InvalidToken();

        ClankerV4Settings storage c = LibAppStorage.clankerV4Settings();

        uint256 tokensBefore = IERC20(cabal.tokenAddress).balanceOf(address(this));

        _executeBuySwap(cabal.tokenAddress, c.hook, uint128(msg.value), uint128(minAmountOut), hookData);

        uint256 tokensAfter = IERC20(cabal.tokenAddress).balanceOf(address(this));
        amountOut = tokensAfter - tokensBefore;

        if (amountOut < minAmountOut) revert SlippageExceeded();

        // Transfer tokens to buyer
        IERC20(cabal.tokenAddress).transfer(msg.sender, amountOut);

        emit TokensBought(cabalId, msg.sender, msg.value, amountOut);

        LibAppStorage.logActivity(cabalId, msg.sender, ActivityType.Bought, msg.value);
    }

    // ============ Sell Function ============

    /**
     * @notice Sell Cabal tokens for ETH
     */
    function sellTokens(
        uint256 cabalId,
        uint256 tokenAmount,
        uint256 minEthOut
    ) external returns (uint256 ethOut) {
        return sellTokensWithHookData(cabalId, tokenAmount, minEthOut, bytes(""));
    }

    /**
     * @notice Sell Cabal tokens with hook data
     * @dev Trading fees are handled at the Clanker hook level (collected in ClankerFeeLocker)
     */
    function sellTokensWithHookData(
        uint256 cabalId,
        uint256 tokenAmount,
        uint256 minEthOut,
        bytes memory hookData
    ) public returns (uint256 ethOut) {
        if (tokenAmount == 0) revert ZeroAmount();

        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.phase != CabalPhase.Active) revert CabalNotActive();
        if (cabal.phase == CabalPhase.Closed) revert CabalClosed();
        if (cabal.tokenAddress == address(0)) revert InvalidToken();

        ClankerV4Settings storage c = LibAppStorage.clankerV4Settings();

        // Transfer tokens from seller
        IERC20(cabal.tokenAddress).transferFrom(msg.sender, address(this), tokenAmount);

        // Approve tokens to Permit2, then Permit2 to Universal Router
        IERC20(cabal.tokenAddress).approve(PERMIT2, tokenAmount);
        IPermit2(PERMIT2).approve(cabal.tokenAddress, UNIVERSAL_ROUTER, uint160(tokenAmount), uint48(block.timestamp + 300));

        uint256 ethBefore = address(this).balance;

        _executeSellSwap(cabal.tokenAddress, c.hook, uint128(tokenAmount), uint128(minEthOut), hookData);

        ethOut = address(this).balance - ethBefore;

        if (ethOut < minEthOut) revert SlippageExceeded();

        // Transfer ETH to seller
        (bool success, ) = msg.sender.call{value: ethOut}("");
        require(success, "ETH transfer failed");

        emit TokensSold(cabalId, msg.sender, tokenAmount, ethOut);

        LibAppStorage.logActivity(cabalId, msg.sender, ActivityType.Sold, ethOut);
    }

    // ============ Internal Swap Functions ============

    /**
     * @notice Execute a buy swap (ETH -> Token) using Uniswap V4 Universal Router
     * @dev Uses WRAP_ETH command, then V4_SWAP with SETTLE (payerIsUser=false)
     */
    function _executeBuySwap(
        address token,
        address hook,
        uint128 amountIn,
        uint128 minAmountOut,
        bytes memory hookData
    ) internal {
        // Determine pool ordering (currency0 must be < currency1)
        bool isWethCurrency0 = WETH < token;

        // Build PoolKey using official types
        PoolKey memory poolKey = PoolKey({
            currency0: Currency.wrap(isWethCurrency0 ? WETH : token),
            currency1: Currency.wrap(isWethCurrency0 ? token : WETH),
            fee: DEFAULT_FEE,
            tickSpacing: DEFAULT_TICK_SPACING,
            hooks: IHooks(hook)
        });

        // For buying token with ETH:
        // - If WETH is currency0, we swap currency0 -> currency1 (zeroForOne = true)
        // - If WETH is currency1, we swap currency1 -> currency0 (zeroForOne = false)
        bool zeroForOne = isWethCurrency0;

        // ========== Build V4_SWAP Input ==========
        // Actions sequence for ETH -> Token swap:
        // 1. SWAP_EXACT_IN_SINGLE - perform the swap
        // 2. SETTLE - settle the WETH input (payerIsUser=false means use router's balance)
        // 3. TAKE_ALL - take the token output
        bytes memory actions = abi.encodePacked(
            uint8(Actions.SWAP_EXACT_IN_SINGLE),
            uint8(Actions.SETTLE),
            uint8(Actions.TAKE_ALL)
        );

        // Prepare parameters for each action
        bytes[] memory params = new bytes[](3);

        // Param 0: ExactInputSingleParams for SWAP_EXACT_IN_SINGLE
        params[0] = abi.encode(
            IV4Router.ExactInputSingleParams({
                poolKey: poolKey,
                zeroForOne: zeroForOne,
                amountIn: amountIn,
                amountOutMinimum: minAmountOut,
                hookData: hookData
            })
        );

        // Param 1: SETTLE - (currency, amount, payerIsUser)
        // payerIsUser=false means use router's balance (WETH from WRAP_ETH)
        params[1] = abi.encode(
            Currency.wrap(WETH),
            uint256(amountIn),
            false  // payerIsUser = false (router pays from its own balance)
        );

        // Param 2: TAKE_ALL - (currency, minAmount)
        // We're receiving the token (the output currency)
        params[2] = abi.encode(
            Currency.wrap(token),
            minAmountOut
        );

        // ========== Build Universal Router Commands ==========
        // Commands: WRAP_ETH (wrap native ETH to WETH in router), V4_SWAP, SWEEP
        bytes memory commands = abi.encodePacked(
            uint8(Commands.WRAP_ETH),
            uint8(Commands.V4_SWAP),
            uint8(Commands.SWEEP)
        );

        // Build inputs array (one per command)
        bytes[] memory inputs = new bytes[](3);

        // Input 0: WRAP_ETH - (recipient, amount)
        // Recipient is ADDRESS_THIS (router) which will hold WETH for the swap
        inputs[0] = abi.encode(ADDRESS_THIS, uint256(amountIn));

        // Input 1: V4_SWAP - (actions, params)
        inputs[1] = abi.encode(actions, params);

        // Input 2: SWEEP - (token, recipient, amountMin)
        // Sweep output tokens from router to caller (Diamond)
        inputs[2] = abi.encode(token, MSG_SENDER, uint256(0));

        // Execute with native ETH
        IUniversalRouter(UNIVERSAL_ROUTER).execute{value: amountIn}(
            commands,
            inputs,
            block.timestamp + 300
        );
    }

    /**
     * @notice Execute a sell swap (Token -> ETH) using Uniswap V4 Universal Router
     * @dev Uses V4_SWAP with SETTLE_ALL (for user's tokens via Permit2), then UNWRAP_WETH
     */
    function _executeSellSwap(
        address token,
        address hook,
        uint128 amountIn,
        uint128 minAmountOut,
        bytes memory hookData
    ) internal {
        // Determine pool ordering
        bool isWethCurrency0 = WETH < token;

        // Build PoolKey
        PoolKey memory poolKey = PoolKey({
            currency0: Currency.wrap(isWethCurrency0 ? WETH : token),
            currency1: Currency.wrap(isWethCurrency0 ? token : WETH),
            fee: DEFAULT_FEE,
            tickSpacing: DEFAULT_TICK_SPACING,
            hooks: IHooks(hook)
        });

        // For selling token for ETH:
        // - If WETH is currency0, we swap currency1 -> currency0 (zeroForOne = false)
        // - If WETH is currency1, we swap currency0 -> currency1 (zeroForOne = true)
        bool zeroForOne = !isWethCurrency0;

        // ========== Build V4_SWAP Input ==========
        // Actions sequence for Token -> ETH swap:
        // 1. SWAP_EXACT_IN_SINGLE - perform the swap  
        // 2. SETTLE_ALL - settle the token input (pulled from user via Permit2)
        // 3. TAKE_ALL - take the WETH output
        bytes memory actions = abi.encodePacked(
            uint8(Actions.SWAP_EXACT_IN_SINGLE),
            uint8(Actions.SETTLE_ALL),
            uint8(Actions.TAKE_ALL)
        );

        bytes[] memory params = new bytes[](3);

        // Param 0: ExactInputSingleParams for SWAP_EXACT_IN_SINGLE
        params[0] = abi.encode(
            IV4Router.ExactInputSingleParams({
                poolKey: poolKey,
                zeroForOne: zeroForOne,
                amountIn: amountIn,
                amountOutMinimum: minAmountOut,
                hookData: hookData
            })
        );

        // Param 1: SETTLE_ALL - paying with token (maxAmount)
        params[1] = abi.encode(
            Currency.wrap(token),
            amountIn
        );

        // Param 2: TAKE_ALL - receiving WETH (minAmount)
        params[2] = abi.encode(
            Currency.wrap(WETH),
            minAmountOut
        );

        // ========== Build Universal Router Commands ==========
        // Commands: V4_SWAP, UNWRAP_WETH
        bytes memory commands = abi.encodePacked(
            uint8(Commands.V4_SWAP),
            uint8(Commands.UNWRAP_WETH)
        );

        bytes[] memory inputs = new bytes[](2);

        // Input 0: V4_SWAP
        inputs[0] = abi.encode(actions, params);

        // Input 1: UNWRAP_WETH - (recipient, amountMin)
        // Unwrap WETH and send ETH to caller (Diamond)
        inputs[1] = abi.encode(MSG_SENDER, uint256(0));

        // Execute (no ETH value for sell)
        IUniversalRouter(UNIVERSAL_ROUTER).execute(
            commands,
            inputs,
            block.timestamp + 300
        );
    }

    // ============ View Functions ============

    function getPoolKey(uint256 cabalId) external view returns (
        address currency0, address currency1, uint24 fee, int24 tickSpacing, address hooks
    ) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        ClankerV4Settings storage c = LibAppStorage.clankerV4Settings();

        bool isWeth0 = WETH < cabal.tokenAddress;
        return (
            isWeth0 ? WETH : cabal.tokenAddress,
            isWeth0 ? cabal.tokenAddress : WETH,
            DEFAULT_FEE,
            DEFAULT_TICK_SPACING,
            c.hook
        );
    }

    function hasActivePool(uint256 cabalId) external view returns (bool) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        return cabal.phase == CabalPhase.Active && cabal.tokenAddress != address(0);
    }

    // Stub functions to maintain ABI compatibility
    function quoteBuy(uint256, uint256) external pure returns (uint256) {
        return 0;
    }

    function quoteSell(uint256, uint256) external pure returns (uint256) {
        return 0;
    }

    // TEMPORARY ADMIN FUNCTION
    function setCabalToken(uint256 cabalId, address token) external {
        LibAppStorage.getCabalData(cabalId).tokenAddress = token;
        LibAppStorage.getCabalData(cabalId).phase = CabalPhase.Active;
    }

    receive() external payable {}
}

contracts/cabal/diamond/facets/TokenRece.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155Receiver.sol";

/**
 * @title TokenReceiverFacet
 * @notice Enables the Diamond to receive ERC721 and ERC1155 tokens via safe transfers
 * @dev Required for CabalNFT.mint() which uses _safeMint
 */
contract TokenReceiverFacet is IERC721Receiver, IERC1155Receiver {
    
    /**
     * @notice Handle the receipt of an ERC721 token
     * @dev Returns the magic value to indicate successful receipt
     */
    function onERC721Received(
        address /* operator */,
        address /* from */,
        uint256 /* tokenId */,
        bytes calldata /* data */
    ) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    /**
     * @notice Handle the receipt of a single ERC1155 token
     */
    function onERC1155Received(
        address /* operator */,
        address /* from */,
        uint256 /* id */,
        uint256 /* value */,
        bytes calldata /* data */
    ) external pure override returns (bytes4) {
        return IERC1155Receiver.onERC1155Received.selector;
    }

    /**
     * @notice Handle the receipt of multiple ERC1155 tokens
     */
    function onERC1155BatchReceived(
        address /* operator */,
        address /* from */,
        uint256[] calldata /* ids */,
        uint256[] calldata /* values */,
        bytes calldata /* data */
    ) external pure override returns (bytes4) {
        return IERC1155Receiver.onERC1155BatchReceived.selector;
    }

    /**
     * @notice Query if a contract implements an interface
     * @dev ERC165 compliance
     */
    function supportsInterface(bytes4 interfaceId) external pure override returns (bool) {
        return 
            interfaceId == type(IERC721Receiver).interfaceId ||
            interfaceId == type(IERC1155Receiver).interfaceId ||
            interfaceId == 0x01ffc9a7; // ERC165
    }
}

contracts/cabal/diamond/facets/TreasuryF.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { LibAppStorage, AppStorage, CabalData, CabalPhase, ActivityType } from "../libraries/LibAppStorage.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title IClankerFeeLocker
 * @notice Interface for Clanker's fee locker contract
 */
interface IClankerFeeLocker {
    function claim(address feeOwner, address token) external;
    function availableFees(address feeOwner, address token) external view returns (uint256);
}

/**
 * @title TreasuryFacet
 * @notice Handles treasury operations, LP fee claiming, and predefined proposal helpers
 */
contract TreasuryFacet {
    // ============ Events ============

    event LPFeesClaimed(
        uint256 indexed cabalId,
        address indexed token,
        uint256 amount
    );

    // ============ Errors ============

    error CabalNotActive();
    error ClaimFailed();

    // ============ LP Fee Functions (Permissionless) ============

    /**
     * @notice Claim LP fees from Clanker FeeLocker
     * @param cabalId The Cabal to claim for
     * @param token The token to claim (e.g., WETH)
     * @dev Anyone can call this - fees go to TBA
     */
    function claimLPFees(uint256 cabalId, address token) external {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.phase != CabalPhase.Active) revert CabalNotActive();

        AppStorage storage s = LibAppStorage.appStorage();

        // Get current balance before claim
        uint256 balanceBefore = IERC20(token).balanceOf(cabal.tbaAddress);

        // TBA calls FeeLocker.claim(tbaAddress, token)
        bytes memory claimCalldata = abi.encodeWithSelector(
            IClankerFeeLocker.claim.selector,
            cabal.tbaAddress,
            token
        );

        (bool success, ) = cabal.tbaAddress.call(
            abi.encodeWithSignature(
                "executeCall(address,uint256,bytes)",
                s.clankerFeeLocker,
                0,
                claimCalldata
            )
        );
        if (!success) revert ClaimFailed();

        // Calculate claimed amount
        uint256 balanceAfter = IERC20(token).balanceOf(cabal.tbaAddress);
        uint256 claimed = balanceAfter - balanceBefore;

        emit LPFeesClaimed(cabalId, token, claimed);

        LibAppStorage.logActivity(cabalId, msg.sender, ActivityType.FeeClaimed, claimed);
    }

    /**
     * @notice Get claimable LP fees
     * @param cabalId The Cabal
     * @param token The token to check
     */
    function getClaimableLPFees(uint256 cabalId, address token) external view returns (uint256) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        AppStorage storage s = LibAppStorage.appStorage();

        return IClankerFeeLocker(s.clankerFeeLocker).availableFees(cabal.tbaAddress, token);
    }

    // ============ View Functions ============

    /**
     * @notice Get ETH balance in treasury
     */
    function getTreasuryETHBalance(uint256 cabalId) external view returns (uint256) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        return cabal.tbaAddress.balance;
    }

    /**
     * @notice Get token balance in treasury
     */
    function getTreasuryTokenBalance(uint256 cabalId, address token) external view returns (uint256) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        return IERC20(token).balanceOf(cabal.tbaAddress);
    }

    /**
     * @notice Get the Cabal's own token balance (excluding staked)
     */
    function getOwnTokenBalance(uint256 cabalId) external view returns (uint256) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
        if (cabal.tokenAddress == address(0)) return 0;

        uint256 totalInTBA = IERC20(cabal.tokenAddress).balanceOf(cabal.tbaAddress);
        // Subtract staked tokens (which are held in TBA)
        return totalInTBA > cabal.totalStaked ? totalInTBA - cabal.totalStaked : 0;
    }

    // ============ Proposal Helpers ============
    // These functions help build calldata for common governance actions
    // They are called off-chain to construct proposals

    /**
     * @notice Build calldata for buying a token on DEX
     * @dev This is a helper - actual swap implementation depends on DEX
     */
    function buildBuyTokenCalldata(
        address router,
        address, /* tokenOut */
        uint256 ethAmount,
        uint256 minAmountOut,
        uint256 deadline
    ) external pure returns (address target, uint256 value, bytes memory data) {
        // Simplified - actual implementation would use Uniswap/DEX router
        target = router;
        value = ethAmount;
        data = abi.encodeWithSignature(
            "swapExactETHForTokens(uint256,address[],address,uint256)",
            minAmountOut,
            new address[](0), // path would be set
            address(0), // to would be TBA
            deadline
        );
    }

    /**
     * @notice Build calldata for contributing to another Cabal's presale
     * @param diamond The CABAL diamond address
     * @param targetCabalId The Cabal to invest in
     */
    function buildInvestInPresaleCalldata(
        address diamond,
        uint256 targetCabalId,
        uint256 ethAmount
    ) external pure returns (address target, uint256 value, bytes memory data) {
        target = diamond;
        value = ethAmount;
        data = abi.encodeWithSignature(
            "contribute(uint256)",
            targetCabalId
        );
    }

    /**
     * @notice Build calldata for transferring ETH
     */
    function buildTransferETHCalldata(
        address to,
        uint256 amount
    ) external pure returns (address target, uint256 value, bytes memory data) {
        target = to;
        value = amount;
        data = "";
    }

    /**
     * @notice Build calldata for transferring tokens
     */
    function buildTransferTokenCalldata(
        address token,
        address to,
        uint256 amount
    ) external pure returns (address target, uint256 value, bytes memory data) {
        target = token;
        value = 0;
        data = abi.encodeWithSelector(
            IERC20.transfer.selector,
            to,
            amount
        );
    }
}

contracts/cabal/diamond/facets/ViewFacet.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { LibAppStorage, AppStorage, CabalData, CabalPhase, GovernanceSettings } from "../libraries/LibAppStorage.sol";

/**
 * @title ViewFacet
 * @notice Read-only functions for querying Cabal data
 * @dev Contains unique batch queries - individual getters are in their respective facets
 */
contract ViewFacet {
    // ============ Structs for Return Types ============

    struct CabalInfo {
        uint256 id;
        address creator;
        string name;
        string symbol;
        string image;
        address tbaAddress;
        address tokenAddress;
        CabalPhase phase;
        uint256 createdAt;
        uint256 launchedAt;
        uint256 totalRaised;
        uint256 totalTokensReceived;
        uint256 totalStaked;
        uint256 contributorCount;
        GovernanceSettings settings;
        uint256 parentCabalId;  // Parent in hierarchy (0 for root/legacy)
    }

    struct CabalHierarchy {
        uint256 cabalId;
        uint256 parentId;
        uint256[] childIds;
        CabalPhase phase;
        string symbol;
    }

    struct TreeNode {
        uint256 cabalId;
        uint256 parentId;
    }

    // ============ Cabal Queries ============

    /**
     * @notice Get full Cabal info
     */
    function getCabal(uint256 cabalId) external view returns (CabalInfo memory) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);

        return CabalInfo({
            id: cabalId,
            creator: cabal.creator,
            name: cabal.name,
            symbol: cabal.symbol,
            image: cabal.image,
            tbaAddress: cabal.tbaAddress,
            tokenAddress: cabal.tokenAddress,
            phase: cabal.phase,
            createdAt: cabal.createdAt,
            launchedAt: cabal.launchedAt,
            totalRaised: cabal.totalRaised,
            totalTokensReceived: cabal.totalTokensReceived,
            totalStaked: cabal.totalStaked,
            contributorCount: cabal.contributors.length,
            settings: cabal.settings,
            parentCabalId: cabal.parentCabalId
        });
    }

    /**
     * @notice Get all Cabal IDs
     */
    function getAllCabals() external view returns (uint256[] memory) {
        return LibAppStorage.appStorage().allCabalIds;
    }

    /**
     * @notice Get total number of Cabals
     */
    function getTotalCabals() external view returns (uint256) {
        return LibAppStorage.appStorage().allCabalIds.length;
    }

    /**
     * @notice Get paginated Cabals with full info (newest first)
     * @param offset Number of cabals to skip from the newest
     * @param limit Maximum number of cabals to return
     * @return cabals Array of CabalInfo structs
     * @return total Total number of cabals (for calculating hasMore on frontend)
     */
    function getCabalsPaginated(uint256 offset, uint256 limit) external view returns (
        CabalInfo[] memory cabals,
        uint256 total
    ) {
        uint256[] storage allIds = LibAppStorage.appStorage().allCabalIds;
        total = allIds.length;

        // If offset is beyond total, return empty
        if (offset >= total) {
            return (new CabalInfo[](0), total);
        }

        // Calculate how many we can actually return
        uint256 remaining = total - offset;
        uint256 count = remaining < limit ? remaining : limit;

        cabals = new CabalInfo[](count);

        // Iterate backwards (newest first)
        // newest = allIds[total - 1], so with offset 0, start at total - 1
        // with offset 5, start at total - 1 - 5 = total - 6
        for (uint256 i = 0; i < count; i++) {
            uint256 reverseIndex = total - 1 - offset - i;
            uint256 cabalId = allIds[reverseIndex];
            CabalData storage cabal = LibAppStorage.getCabalData(cabalId);

            cabals[i] = CabalInfo({
                id: cabalId,
                creator: cabal.creator,
                name: cabal.name,
                symbol: cabal.symbol,
                image: cabal.image,
                tbaAddress: cabal.tbaAddress,
                tokenAddress: cabal.tokenAddress,
                phase: cabal.phase,
                createdAt: cabal.createdAt,
                launchedAt: cabal.launchedAt,
                totalRaised: cabal.totalRaised,
                totalTokensReceived: cabal.totalTokensReceived,
                totalStaked: cabal.totalStaked,
                contributorCount: cabal.contributors.length,
                settings: cabal.settings,
                parentCabalId: cabal.parentCabalId
            });
        }
    }

    /**
     * @notice Get Cabals created by an address
     */
    function getCabalsByCreator(address creator) external view returns (uint256[] memory) {
        return LibAppStorage.getCreatorCabals(creator);
    }

    /**
     * @notice Get Cabals where user has stake
     */
    function getCabalsByStaker(address staker) external view returns (uint256[] memory) {
        return LibAppStorage.getUserStakedCabals(staker);
    }

    // ============ Contribution Queries (unique to this facet) ============

    /**
     * @notice Get user's contribution to a Cabal
     */
    function getContribution(uint256 cabalId, address user) external view returns (uint256) {
        return LibAppStorage.getContribution(cabalId, user);
    }

    // NOTE: hasClaimed() has been removed. Tokens are now auto-staked at launch.
    // Users should use StakingFacet.unstake() to withdraw their tokens.

    // ============ Batch Queries ============

    /**
     * @notice Get multiple Cabals at once
     */
    function getCabals(uint256[] calldata cabalIds) external view returns (CabalInfo[] memory) {
        CabalInfo[] memory infos = new CabalInfo[](cabalIds.length);

        for (uint256 i = 0; i < cabalIds.length; i++) {
            CabalData storage cabal = LibAppStorage.getCabalData(cabalIds[i]);
            infos[i] = CabalInfo({
                id: cabalIds[i],
                creator: cabal.creator,
                name: cabal.name,
                symbol: cabal.symbol,
                image: cabal.image,
                tbaAddress: cabal.tbaAddress,
                tokenAddress: cabal.tokenAddress,
                phase: cabal.phase,
                createdAt: cabal.createdAt,
                launchedAt: cabal.launchedAt,
                totalRaised: cabal.totalRaised,
                totalTokensReceived: cabal.totalTokensReceived,
                totalStaked: cabal.totalStaked,
                contributorCount: cabal.contributors.length,
                settings: cabal.settings,
                parentCabalId: cabal.parentCabalId
            });
        }

        return infos;
    }

    /**
     * @notice Get user's position in multiple Cabals
     * @dev Tokens are now auto-staked at launch - no more claim tracking
     */
    function getUserPositions(address user, uint256[] calldata cabalIds) external view returns (
        uint256[] memory contributions,
        uint256[] memory stakedBalances,
        uint256[] memory votingPowers
    ) {
        contributions = new uint256[](cabalIds.length);
        stakedBalances = new uint256[](cabalIds.length);
        votingPowers = new uint256[](cabalIds.length);

        for (uint256 i = 0; i < cabalIds.length; i++) {
            uint256 cabalId = cabalIds[i];

            contributions[i] = LibAppStorage.getContribution(cabalId, user);
            stakedBalances[i] = LibAppStorage.getStakedBalance(cabalId, user);

            // Voting power = staked + delegated (if not delegating away)
            uint256 delegatedToMe = LibAppStorage.getDelegatedPower(cabalId, user);
            address delegatee = LibAppStorage.getDelegatee(cabalId, user);
            votingPowers[i] = delegatee != address(0) ? delegatedToMe : stakedBalances[i] + delegatedToMe;
        }
    }

    // ============ Hierarchy Queries ============

    /**
     * @notice Get hierarchy info for a single cabal
     * @param cabalId The cabal to get hierarchy for
     * @return hierarchy Parent ID and child IDs
     */
    function getCabalHierarchy(uint256 cabalId) external view returns (CabalHierarchy memory hierarchy) {
        CabalData storage cabal = LibAppStorage.getCabalData(cabalId);

        hierarchy = CabalHierarchy({
            cabalId: cabalId,
            parentId: cabal.parentCabalId,
            childIds: cabal.childCabalIds,
            phase: cabal.phase,
            symbol: cabal.symbol
        });
    }

    /**
     * @notice Get the full tree structure (all cabals with their parent IDs)
     * @return nodes Array of TreeNode structs containing all cabals
     * @dev Optimized for graph visualization - minimal data per node
     */
    function getFullTree() external view returns (TreeNode[] memory nodes) {
        uint256[] storage allIds = LibAppStorage.appStorage().allCabalIds;
        nodes = new TreeNode[](allIds.length);

        for (uint256 i = 0; i < allIds.length; i++) {
            uint256 cabalId = allIds[i];
            CabalData storage cabal = LibAppStorage.getCabalData(cabalId);

            nodes[i] = TreeNode({
                cabalId: cabalId,
                parentId: cabal.parentCabalId
            });
        }
    }

    /**
     * @notice Get only hierarchical cabals (CABAL0 and its descendants)
     * @return ids Array of cabal IDs that are part of the fractal hierarchy
     * @dev Excludes legacy cabals (those with parentCabalId=0 that aren't CABAL0)
     */
    function getHierarchicalCabalIds() external view returns (uint256[] memory ids) {
        if (!LibAppStorage.isGenesisInitialized()) {
            return new uint256[](0);
        }

        uint256 rootId = LibAppStorage.getRootCabalId();
        uint256[] storage allIds = LibAppStorage.appStorage().allCabalIds;

        // First pass: count hierarchical cabals
        uint256 count = 0;
        for (uint256 i = 0; i < allIds.length; i++) {
            uint256 cabalId = allIds[i];
            CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
            // Include if: is root cabal OR is a child of any cabal (check childCabalIds)
            // Use TBA address as indicator - hierarchical cabals have valid TBAs
            if (cabalId == rootId || cabal.tbaAddress != address(0)) {
                count++;
            }
        }

        // Second pass: collect hierarchical cabal IDs
        ids = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < allIds.length; i++) {
            uint256 cabalId = allIds[i];
            CabalData storage cabal = LibAppStorage.getCabalData(cabalId);
            if (cabalId == rootId || cabal.tbaAddress != address(0)) {
                ids[idx++] = cabalId;
            }
        }
    }

    /**
     * @notice Get root cabal ID (CABAL0)
     */
    function getRootCabalId() external view returns (uint256) {
        return LibAppStorage.getRootCabalId();
    }

    /**
     * @notice Check if genesis has been initialized
     */
    function isGenesisInitialized() external view returns (bool) {
        return LibAppStorage.isGenesisInitialized();
    }

    /**
     * @notice Get the protocol treasury address (CABAL0's TBA)
     */
    function getProtocolTreasury() external view returns (address) {
        if (!LibAppStorage.isGenesisInitialized()) return address(0);
        uint256 rootId = LibAppStorage.getRootCabalId();
        return LibAppStorage.getCabalData(rootId).tbaAddress;
    }

    /**
     * @notice Get children of a cabal
     * @param cabalId The parent cabal
     * @return childIds Array of child cabal IDs
     */
    function getChildCabals(uint256 cabalId) external view returns (uint256[] memory childIds) {
        return LibAppStorage.getCabalData(cabalId).childCabalIds;
    }

    /**
     * @notice Get parent of a cabal
     * @param cabalId The child cabal
     * @return parentId Parent cabal ID (0 for root)
     */
    function getParentCabal(uint256 cabalId) external view returns (uint256 parentId) {
        return LibAppStorage.getCabalData(cabalId).parentCabalId;
    }
}

